const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1], N = 2 * n;
const node = (lit) => (lit > 0 ? 2 * (lit - 1) : 2 * (-lit - 1) + 1);
const adj = Array.from({ length: N }, () => []);
const radj = Array.from({ length: N }, () => []);
for (let i = 0; i < m; i++) {
  const a = node(tok[2 + 2 * i]), b = node(tok[3 + 2 * i]);
  adj[a ^ 1].push(b); radj[b].push(a ^ 1);
  adj[b ^ 1].push(a); radj[a].push(b ^ 1);
}
const seen = new Array(N).fill(false);
const order = [];
function dfs1(v) {
  seen[v] = true;
  for (const to of adj[v]) if (!seen[to]) dfs1(to);
  order.push(v);
}
for (let s = 0; s < N; s++) if (!seen[s]) dfs1(s);
const comp = new Array(N).fill(-1);
function dfs2(v, c) {
  comp[v] = c;
  for (const to of radj[v]) if (comp[to] === -1) dfs2(to, c);
}
let c = 0;
for (let i = N - 1; i >= 0; i--) if (comp[order[i]] === -1) dfs2(order[i], c++);
let ok = true;
for (let i = 0; i < n; i++) if (comp[2 * i] === comp[2 * i + 1]) ok = false;
console.log(ok ? "YES" : "NO");

