import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] adj, radj;
    static boolean[] seen;
    static int[] order, comp;
    static int cnt = 0;

    static int node(int lit) { return lit > 0 ? 2 * (lit - 1) : 2 * (-lit - 1) + 1; }

    static void dfs1(int v) {
        seen[v] = true;
        for (int to : adj[v]) if (!seen[to]) dfs1(to);
        order[cnt++] = v;
    }

    static void dfs2(int v, int c) {
        comp[v] = c;
        for (int to : radj[v]) if (comp[to] == -1) dfs2(to, c);
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(null, () -> {
            try { solve(); } catch (IOException e) { throw new RuntimeException(e); }
        }, "main", 1 << 26);
        t.start();
        t.join();
    }

    @SuppressWarnings("unchecked")
    static void solve() throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval, N = 2 * n;
        adj = new List[N];
        radj = new List[N];
        for (int i = 0; i < N; i++) { adj[i] = new ArrayList<>(); radj[i] = new ArrayList<>(); }
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int a = node((int) in.nval);
            in.nextToken();
            int b = node((int) in.nval);
            adj[a ^ 1].add(b); radj[b].add(a ^ 1);
            adj[b ^ 1].add(a); radj[a].add(b ^ 1);
        }
        seen = new boolean[N];
        order = new int[N];
        comp = new int[N];
        Arrays.fill(comp, -1);
        for (int s = 0; s < N; s++) if (!seen[s]) dfs1(s);
        int c = 0;
        for (int i = N - 1; i >= 0; i--) if (comp[order[i]] == -1) dfs2(order[i], c++);
        boolean ok = true;
        for (int i = 0; i < n; i++) if (comp[2 * i] == comp[2 * i + 1]) ok = false;
        System.out.println(ok ? "YES" : "NO");
    }
}

