#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj, radj;
vector<bool> seen;
vector<int> order_, comp;

int node(int lit) { return lit > 0 ? 2 * (lit - 1) : 2 * (-lit - 1) + 1; }
void dfs1(int v) {
    seen[v] = true;
    for (int to : adj[v]) if (!seen[to]) dfs1(to);
    order_.push_back(v);
}
void dfs2(int v, int c) {
    comp[v] = c;
    for (int to : radj[v]) if (comp[to] == -1) dfs2(to, c);
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    int N = 2 * n;
    adj.assign(N, {});
    radj.assign(N, {});
    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        int a = node(x), b = node(y);
        adj[a ^ 1].push_back(b); radj[b].push_back(a ^ 1);
        adj[b ^ 1].push_back(a); radj[a].push_back(b ^ 1);
    }
    seen.assign(N, false);
    comp.assign(N, -1);
    for (int s = 0; s < N; s++) if (!seen[s]) dfs1(s);
    int c = 0;
    for (int i = N - 1; i >= 0; i--) if (comp[order_[i]] == -1) dfs2(order_[i], c++);
    bool ok = true;
    for (int i = 0; i < n; i++) if (comp[2 * i] == comp[2 * i + 1]) ok = false;
    puts(ok ? "YES" : "NO");
    return 0;
}
